import { LightningElement, api } from 'lwc';

let uid = 0;

/**
 * Keys intercepted by the listbox. For these, and only these, we call
 * preventDefault(); every other key (notably Tab) keeps its default behaviour.
 */
const NAVIGATION_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    /** Accessible name of the list, rendered as aria-label. */
    @api label;

    /** Options to render: Array of { value, label }. */
    @api options = [];

    /** Currently selected value (owned by the parent). */
    _value;

    /** Value of the "active" (visually focused) option. */
    _activeValue;

    /** Id of the option scrolled into view by the last render. */
    _lastScrolledId = null;

    /** Unique-per-instance prefix for option ids (aria-activedescendant). */
    _idPrefix = `status-listbox-${++uid}`;

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue;
        // When the parent changes value, the active option moves to it.
        // (If newValue is not present in options, the derived getter falls
        // back to the selected option or the first option.)
        this._activeValue = newValue;
    }

    renderedCallback() {
        const activeId = this.activeDescendantId;
        if (!activeId || activeId === this._lastScrolledId) {
            return;
        }
        this._lastScrolledId = activeId;
        const activeOption = Array.from(
            this.template.querySelectorAll('li[role="option"]'),
        ).find((el) => el.id === activeId);
        if (activeOption) {
            activeOption.scrollIntoView({ block: 'nearest' });
        }
    }

    /* ------------------------------------------------------------------ *
     * Derived state
     * ------------------------------------------------------------------ */

    _optionId(index) {
        return `${this._idPrefix}-option-${index}`;
    }

    /**
     * Index of the active option:
     * - the option whose value is the internal active value, if present;
     * - otherwise the selected option, if present;
     * - otherwise the first option.
     * Returns -1 when there are no options.
     */
    get activeIndex() {
        const options = this.options ?? [];
        if (options.length === 0) {
            return -1;
        }
        const activeIdx = options.findIndex(
            (option) => option.value === this._activeValue,
        );
        if (activeIdx !== -1) {
            return activeIdx;
        }
        const selectedIdx = options.findIndex(
            (option) => option.value === this._value,
        );
        return selectedIdx !== -1 ? selectedIdx : 0;
    }

    get activeDescendantId() {
        const index = this.activeIndex;
        return index === -1 ? null : this._optionId(index);
    }

    get renderedOptions() {
        const activeIndex = this.activeIndex;
        return (this.options ?? []).map((option, index) => ({
            ...option,
            index,
            id: this._optionId(index),
            isSelected: option.value === this._value ? 'true' : 'false',
            className:
                index === activeIndex
                    ? 'status-listbox__option status-listbox__option_active'
                    : 'status-listbox__option',
        }));
    }

    /* ------------------------------------------------------------------ *
     * Event handlers
     * ------------------------------------------------------------------ */

    handleKeydown(event) {
        const options = this.options ?? [];
        if (options.length === 0) {
            return;
        }
        const { key } = event;
        if (!NAVIGATION_KEYS.includes(key)) {
            // Tab and all other keys keep their default behaviour.
            return;
        }
        event.preventDefault();
        switch (key) {
            case 'ArrowDown':
                this._moveActive(1);
                break;
            case 'ArrowUp':
                this._moveActive(-1);
                break;
            case 'Home':
                this._moveActive(-Infinity);
                break;
            case 'End':
                this._moveActive(Infinity);
                break;
            default:
                // 'Enter' or ' ' (space): select the active option.
                this._selectIndex(this.activeIndex);
                break;
        }
    }

    handleClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        this._selectIndex(index);
    }

    /* ------------------------------------------------------------------ *
     * Internal helpers
     * ------------------------------------------------------------------ */

    /**
     * Move the active option by delta, clamped to the bounds of the list
     * (no wrap-around). Moving never changes the selection.
     */
    _moveActive(delta) {
        const options = this.options ?? [];
        if (options.length === 0) {
            return;
        }
        const next = Math.min(
            Math.max(this.activeIndex + delta, 0),
            options.length - 1,
        );
        this._activeValue = options[next].value;
    }

    /**
     * Select the option at index: make it active, update the selection and
     * dispatch a change event — unless it was already selected, in which
     * case nothing is dispatched.
     */
    _selectIndex(index) {
        const options = this.options ?? [];
        const option = options[index];
        if (!option) {
            return;
        }
        this._activeValue = option.value;
        if (option.value === this._value) {
            return;
        }
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                bubbles: true,
                composed: true,
                detail: { value: option.value },
            }),
        );
    }
}
