public inherited sharing class FamilyService {

    private static final String STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Dedupe, drop blanks and self-links.
        Map<Id, Id> pairsToCreate = new Map<Id, Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) continue;
            if (childId == parentId) continue;
            pairsToCreate.put(childId, parentId);
        }
        if (pairsToCreate.isEmpty()) {
            return;
        }

        // Every contact we might match on.
        Set<Id> contactIds = new Set<Id>();
        contactIds.addAll(pairsToCreate.keySet());
        contactIds.addAll(pairsToCreate.values());

        // One SOQL: every existing relationship touching any of these contacts.
        Map<String, Boolean> existingPairs = new Map<String, Boolean>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :contactIds
               OR npe4__RelatedContact__c IN :contactIds
        ]) {
            existingPairs.put(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c), true);
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : pairsToCreate.keySet()) {
            Id parentId = pairsToCreate.get(childId);
            if (existingPairs.containsKey(pairKey(childId, parentId))
                    || existingPairs.containsKey(pairKey(parentId, childId))) {
                continue; // already linked in either direction
            }
            // Record "parent is child's Parent"; NPSP's reciprocal machinery
            // (List Setting + Parent lookup: Male Son / Female Daughter /
            // Neutral Child) creates the child→parent mirror, so we insert
            // exactly one row per direction per pair.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        if (!toInsert.isEmpty()) {
            insert toInsert; // single DML
        }
    }

    private static String pairKey(Id a, Id b) {
        return String.valueOf(a) + '>' + String.valueOf(b);
    }
}
