/**
 * @description Creates an onboarding Task for the owner of each newly created
 *              Account whose Type is a customer type.
 *
 * Registered via Trigger_Action__mdt (DeveloperName: TA_Account_CreateOnboardingTask)
 * in the After Insert context of the Account sObject_Trigger_Setting__mdt record.
 *
 * Bulkified: all Tasks are inserted with a single DML statement per trigger
 * execution, and no DML is performed when no Account qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final String SUBJECT = 'Onboard new customer';
    private static final String STATUS_NOT_STARTED = 'Not Started';
    private static final String PRIORITY_NORMAL = 'Normal';

    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    /**
     * @description Called by the Trigger Actions Framework after Account records
     *              are inserted. Collects every qualifying Account, builds one
     *              Task per qualifying Account, and inserts them all in a single
     *              DML statement. Performs no DML when nothing qualifies.
     * @param triggerNew The List of Accounts passed in from the trigger.
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Task> onboardingTasks = buildOnboardingTasks(triggerNew);

        if (onboardingTasks.isEmpty()) {
            // No qualifying Accounts in this chunk: no DML at all.
            return;
        }

        // Single DML statement per trigger execution.
        insert onboardingTasks;
    }

    /**
     * @description Builds the onboarding Task for every Account that qualifies.
     * @param accounts The List of Accounts passed in from the trigger.
     * @return The List of Tasks to insert (may be empty).
     */
    private List<Task> buildOnboardingTasks(List<SObject> accounts) {
        List<Task> onboardingTasks = new List<Task>();
        if (accounts == null || accounts.isEmpty()) {
            return onboardingTasks;
        }

        Date activityDate = Date.today().addDays(7);

        for (SObject account : accounts) {
            if (!qualifiesForOnboarding(account)) {
                continue;
            }

            Task onboardingTask = new Task(
                Subject = SUBJECT,
                WhatId = account.Id,
                OwnerId = (Id) account.get('OwnerId'),
                ActivityDate = activityDate,
                Status = STATUS_NOT_STARTED,
                Priority = PRIORITY_NORMAL
            );
            onboardingTasks.add(onboardingTask);
        }

        return onboardingTasks;
    }

    /**
     * @description Determines whether an Account qualifies for an onboarding Task.
     * @param account The Account record to evaluate.
     * @return true if the Account Type is a customer type and required fields are populated.
     */
    private Boolean qualifiesForOnboarding(SObject account) {
        Map<String, Object> populatedFields = account.getPopulatedFieldsAsMap();

        if (!populatedFields.containsKey('Type') || account.get('Type') == null) {
            return false;
        }
        if (!ONBOARDING_ACCOUNT_TYPES.contains((String) account.get('Type'))) {
            return false;
        }
        // The Task needs an Account Id (WhatId) and an OwnerId; in the after
        // insert context the Id is always available, and OwnerId is populated
        // on trigger records, but guard defensively so a malformed payload
        // skips the record instead of failing the whole chunk.
        return populatedFields.containsKey('Id') && populatedFields.containsKey('OwnerId');
    }
