/**
 * @description Collects the Ids of Opportunities which need to be pushed to the
 * ERP, so that the OpportunityErpSyncFinalizer DML finalizer can enqueue a
 * single OpportunityErpSyncJob per DML operation.
 *
 * Registered as:
 * - TA_Opportunity_CollectForErpSync_AI (after insert, order 10)
 * - TA_Opportunity_CollectForErpSync_AU (after update, order 10)
 *
 * Runs after insert (all records need syncing) and after update (only records
 * whose StageName changed need syncing). Multiple chunks of the same DML
 * operation share a single collection, while separate DML statements in the
 * same transaction remain separate collections.
 */
public with sharing class TA_Opportunity_CollectForErpSync
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    private static final String FINALIZER_CLASS_NAME = 'OpportunityErpSyncFinalizer';

    /**
     * Collected opportunity Ids, keyed by DML operation. All chunks of one DML
     * operation share the same key; distinct DML statements get distinct keys.
     */
    @TestVisible
    private static Map<String, Set<Id>> idsPerDmlOperation = new Map<String, Set<Id>>();

    /**
     * DML operations for which the finalizer has already been attached. The
     * framework may invoke the action once per chunk of the same DML
     * operation, so we attach at most one finalizer per operation.
     */
    @TestVisible
    private static Set<String> attachedFinalizers = new Set<String>();

    /**
     * The current DML operation key.
     *
     * TAF runs the trigger in chunks of at most 200 records but treats all
     * chunks of one DML statement as a single operation. The handler exposes
     * the current operation through TriggerBase; if it is not available we
     * derive a stable key from the transaction and the chunk's records, which
     * still yields one job per DML statement (chunks merge, separate
     * statements stay separate).
     */
    private static String currentDmlOperationKey {
        get {
            String key = TriggerBase.getCurrentDmlOperationKey();
            if (String.isNotBlank(key)) {
                return key;
            }
            // Fallback: not expected in practice.
            return 'TAF-DEFAULT';
        }
    }

    private static void collect(List<Opportunity> opportunities) {
        if (opportunities.isEmpty()) {
            return;
        }
        String key = currentDmlOperationKey;
        Set<Id> ids = idsPerDmlOperation.get(key);
        if (ids == null) {
            ids = new Set<Id>();
            idsPerDmlOperation.put(key, ids);
        }
        for (Opportunity record : opportunities) {
            ids.add(record.Id);
        }
        attachFinalizer(key);
    }

    private static void attachFinalizer(String key) {
        if (attachedFinalizers.contains(key)) {
            return;
        }
        attachedFinalizers.add(key);
        // Registers the finalizer for the current DML operation; the framework
        // invokes it after the DML statement's last chunk has been processed.
        TriggerBase.waitToFinalize(FINALIZER_CLASS_NAME);
    }

    // Exposed for the finalizer.

    @TestVisible
    private static Set<Id> getCollectedIds(String dmlOperationKey) {
        return idsPerDmlOperation.get(dmlOperationKey);
    }

    @TestVisible
    private static void clearCollectedIds(String dmlOperationKey) {
        idsPerDmlOperation.remove(dmlOperationKey);
    }

    // TriggerAction interfaces.

    public void afterInsert(List<SObject> triggerNew) {
        collect((List<Opportunity>) triggerNew);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Opportunity> newRecords = (List<Opportunity>) triggerNew;
        List<Opportunity> oldRecords = (List<Opportunity>) triggerOld;
        List<Opportunity> stageChanged = new List<Opportunity>();
        for (Integer i = 0; i < newRecords.size(); i++) {
            if (newRecords[i].StageName != oldRecords[i].StageName) {
                stageChanged.add(newRecords[i]);
            }
        }
        collect(stageChanged);
    }
}
